import hashlib
import json
from collections import Counter
from datetime import date
from pathlib import Path
from urllib.parse import urlencode

import pandas as pd

from source_io import fetch

BASE_URL = 'https://clinicaltrials.gov/api/v2/studies'
FIELDS = ['NCTId', 'OverallStatus', 'StudyFirstPostDate', 'StudyType', 'Phase', 'Allocation', 'InterventionModel', 'Masking', 'PrimaryPurpose', 'LeadSponsorClass', 'Condition', 'ConditionBrowseBranch', 'InterventionType', 'InterventionName', 'ArmGroupLabel', 'HealthyVolunteers', 'Sex', 'MinimumAge', 'MaximumAge', 'IsFdaRegulatedDrug', 'IsFdaRegulatedDevice', 'StartDate']
FEATURES = ['phase', 'allocation', 'intervention_model', 'masking', 'primary_purpose', 'lead_sponsor_class', 'n_conditions', 'condition_mesh_branch', 'n_interventions', 'intervention_types', 'n_arms', 'healthy_volunteers', 'sex', 'age_bounds', 'is_fda_regulated', 'start_month']
ID_COL = 'nct_id'
TIME_COL = 'first_post_date'
TARGET = 'terminated'
OUTPUT_COLUMNS = [ID_COL, TIME_COL] + FEATURES + [TARGET]
EXPECTED_COUNTS = {'COMPLETED': 105978, 'TERMINATED': 13817}
POP_START = date(2008, 1, 1)
POP_END = date(2017, 1, 1)
TRAIN_START = date(2008, 1, 1)
TRAIN_END = date(2013, 1, 1)
EVAL_START = date(2013, 1, 1)
EVAL_END = date(2015, 1, 1)
HOLDOUT_START = date(2015, 1, 1)
HOLDOUT_END = date(2017, 1, 1)
MAX_PAGES = 500


def _bounded(message):
    return str(message)[:4000]


def _field_failure(prefix, observed_headers, missing, extra=None):
    parts = [prefix, 'observed_headers: ' + repr(observed_headers), 'missing_required_names: ' + repr(missing), 'selected_archive_member: N/A (JSON API; no archive member selected)']
    if extra:
        parts.append('extra_names: ' + repr(extra))
    return _bounded('; '.join(parts))


def _deep(obj, *path):
    value = obj
    for key in path:
        if not isinstance(value, dict):
            return None
        value = value.get(key)
    return value


def _norm(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return 'YES' if value else 'NO'
    text = str(value).strip()
    return text if text else None


def _tri(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    text = str(value).strip().lower()
    if text in ('true', 'yes', 'y', '1'):
        return True
    if text in ('false', 'no', 'n', '0'):
        return False
    return None


def _tri_label(value):
    if value is True:
        return 'YES'
    if value is False:
        return 'NO'
    return 'UNKNOWN'


def _parse_date(value):
    text = _norm(value)
    if text is None:
        return None
    head = text[:10]
    parts = head.split('-')
    if len(parts) != 3:
        return None
    try:
        year_value = int(parts[0])
        month_value = int(parts[1])
        day_value = int(parts[2])
        return date(year_value, month_value, day_value)
    except ValueError:
        return None


def _parse_month(value):
    text = _norm(value)
    if text is None:
        return None
    parts = text[:7].split('-')
    if len(parts) != 2:
        return None
    if len(parts[0]) != 4 or len(parts[1]) != 2:
        return None
    try:
        year_value = int(parts[0])
        month_value = int(parts[1])
    except ValueError:
        return None
    if month_value < 1 or month_value > 12:
        return None
    return (year_value, month_value)


def _age_years(value):
    text = _norm(value)
    if text is None:
        return None
    lowered = text.lower()
    if lowered.startswith('n/a'):
        return None
    number = ''
    for character in text:
        if character.isdigit() or character == '.':
            number += character
        elif number:
            break
        else:
            break
    if not number:
        return None
    try:
        amount = float(number)
    except ValueError:
        return None
    remainder = text[len(number):].strip().lower()
    if remainder.startswith('year'):
        factor = 1.0
    elif remainder.startswith('month'):
        factor = 1.0 / 12.0
    elif remainder.startswith('week'):
        factor = 1.0 / 52.1775
    elif remainder.startswith('day'):
        factor = 1.0 / 365.25
    elif remainder.startswith('hour'):
        factor = 1.0 / 8766.0
    elif remainder == '':
        factor = 1.0
    else:
        factor = None
    if factor is None:
        return None
    return amount * factor


def _record_status(record):
    return _deep(record, 'protocolSection', 'statusModule', 'overallStatus')


def _study_url(status, token):
    params = {
        'filter.advanced': 'AREA[StudyFirstPostDate]RANGE[2008-01-01,2016-12-31] AND AREA[StudyType]INTERVENTIONAL',
        'filter.overallStatus': status,
        'pageSize': 1000,
        'fields': ','.join(FIELDS),
        'countTotal': 'true',
    }
    if token is not None:
        params['pageToken'] = token
    return BASE_URL + '?' + urlencode(params)


def _fetch_status(status, cache):
    rows = []
    total = None
    token = None
    seen = set()
    for page_number in range(MAX_PAGES):
        if token is not None:
            if token in seen:
                raise AssertionError(_bounded('Repeated pagination token for status ' + status + '; selected_archive_member: N/A (JSON API).'))
            seen.add(token)
        url = _study_url(status, token)
        digest = hashlib.sha1((token or 'start').encode('utf-8')).hexdigest()[:12]
        name = 'ctgov_v2_' + status.lower() + '_' + str(page_number).zfill(5) + '_' + digest + '.json'
        local_path = Path(fetch(url, cache, name))
        try:
            with local_path.open('r', encoding='utf-8') as handle:
                payload = json.load(handle)
        except Exception as exc:
            raise AssertionError(_bounded('Could not parse cached API page for status ' + status + '; local_file: ' + str(local_path) + '; selected_archive_member: N/A (JSON API); parser_error: ' + repr(exc))) from exc
        studies = payload.get('studies')
        if not isinstance(studies, list):
            raise AssertionError(_bounded('API page lacks studies list for status ' + status + '; observed_keys: ' + repr(list(payload.keys())) + '; selected_archive_member: N/A (JSON API).'))
        if total is None:
            raw_total = payload.get('totalCount')
            if raw_total is None:
                raise AssertionError(_bounded('API page lacks totalCount for status ' + status + '; observed_keys: ' + repr(list(payload.keys())) + '; selected_archive_member: N/A (JSON API).'))
            total = int(raw_total)
        rows.extend(studies)
        next_token = payload.get('nextPageToken')
        if not next_token:
            break
        token = next_token
    else:
        raise AssertionError(_bounded('Pagination exceeded maximum pages for status ' + status + '; selected_archive_member: N/A (JSON API).'))
    if total is None:
        raise AssertionError(_bounded('No totalCount collected for status ' + status + '; selected_archive_member: N/A (JSON API).'))
    if len(rows) != total:
        raise AssertionError(_bounded('Fetched row count differs from API totalCount for status ' + status + '; observed_fetched_rows: ' + str(len(rows)) + '; observed_totalCount: ' + str(total) + '; selected_archive_member: N/A (JSON API).'))
    bad_statuses = Counter()
    for record in rows:
        observed_status = _record_status(record)
        if observed_status != status:
            bad_statuses[str(observed_status)] += 1
    if bad_statuses:
        raise AssertionError(_bounded('Status filter mismatch for ' + status + '; observed_status_counts: ' + repr(dict(bad_statuses)) + '; selected_archive_member: N/A (JSON API).'))
    return rows, total


def _condition_mesh_branch(record):
    labels = []
    derived = record.get('derivedSection') or {}
    browse = derived.get('conditionBrowseModule') or {}
    for key in ('browseBranches', 'browseBranchesStudy'):
        raw = browse.get(key)
        if raw is None:
            continue
        items = raw if isinstance(raw, list) else [raw]
        for item in items:
            if isinstance(item, dict):
                label = _norm(item.get('name'))
                if label is None:
                    label = _norm(item.get('term'))
                if label is None:
                    label = _norm(item.get('abbrev'))
                if label is None:
                    label = _norm(item.get('branch'))
            else:
                label = _norm(item)
            if label is not None:
                labels.append(label)
    if not labels:
        for key in ('conditionMeshTerm', 'meshes'):
            raw = browse.get(key)
            if raw is None:
                continue
            items = raw if isinstance(raw, list) else [raw]
            for item in items:
                if isinstance(item, dict):
                    label = _norm(item.get('branch'))
                    if label is None:
                        label = _norm(item.get('treeBranch'))
                    if label is not None:
                        labels.append(label)
    if not labels:
        protocol = record.get('protocolSection') or {}
        conditions_block = protocol.get('conditionsModule') or {}
        raw = conditions_block.get('conditionMeshTerm')
        if raw is not None:
            items = raw if isinstance(raw, list) else [raw]
            for item in items:
                if isinstance(item, dict):
                    label = _norm(item.get('branch'))
                    if label is None:
                        label = _norm(item.get('treeBranch'))
                    if label is not None:
                        labels.append(label)
    if not labels:
        return None
    return '|'.join(sorted(set(labels)))


def _parse_record(record):
    protocol = record.get('protocolSection') or {}
    ident = protocol.get('identificationModule') or {}
    status_block = protocol.get('statusModule') or {}
    design = protocol.get('designModule') or {}
    sponsor_block = protocol.get('sponsorCollaboratorsModule') or {}
    conditions_block = protocol.get('conditionsModule') or {}
    arms_block = protocol.get('armsInterventionsModule') or {}
    eligibility_block = protocol.get('eligibilityModule') or {}
    oversight_block = protocol.get('oversightModule') or {}
    nct_id = _norm(ident.get('nctId'))
    if nct_id is None:
        raise AssertionError(_field_failure('Missing NCT ID join key in fetched record', list(record.keys()), ['protocolSection.identificationModule.nctId']))
    overall = _norm(status_block.get('overallStatus'))
    if overall not in ('COMPLETED', 'TERMINATED'):
        raise AssertionError(_bounded('Unexpected terminal status in fetched record for ' + str(nct_id) + '; observed_status: ' + repr(overall) + '; expected: COMPLETED or TERMINATED; selected_archive_member: N/A (JSON API).'))
    first_post_raw = _deep(status_block, 'studyFirstPostDateStruct', 'date')
    if first_post_raw is None:
        first_post_raw = status_block.get('studyFirstPostDate')
    first_post = _parse_date(first_post_raw)
    if first_post is None:
        raise AssertionError(_field_failure('Missing or invalid first-post date for ' + str(nct_id), list(status_block.keys()), ['studyFirstPostDateStruct.date']))
    if first_post < POP_START or first_post >= POP_END:
        raise AssertionError(_bounded('First-post date outside frozen population for ' + str(nct_id) + '; observed_date: ' + str(first_post_raw) + '; expected_window: 2008-01-01 through 2016-12-31; selected_archive_member: N/A (JSON API).'))
    raw_phases = design.get('phases')
    if raw_phases is None:
        raw_phases = design.get('phase')
    phase_values = []
    if isinstance(raw_phases, list):
        for item in raw_phases:
            label = _norm(item)
            if label is not None:
                phase_values.append(label.upper())
    elif raw_phases is not None:
        label = _norm(raw_phases)
        if label is not None:
            phase_values.append(label.upper())
    phase = '|'.join(sorted(set(phase_values))) if phase_values else None
    design_info = design.get('designInfo') or {}
    allocation = _norm(design_info.get('allocation'))
    intervention_model = _norm(design_info.get('interventionModel'))
    masking_info = design_info.get('maskingInfo') or {}
    masking = _norm(masking_info.get('masking'))
    if masking is None:
        masking = _norm(design_info.get('masking'))
    primary_purpose = _norm(design_info.get('primaryPurpose'))
    lead_sponsor = sponsor_block.get('leadSponsor') or {}
    lead_sponsor_class = _norm(lead_sponsor.get('class'))
    raw_conditions = conditions_block.get('conditions')
    if isinstance(raw_conditions, list):
        n_conditions = len(raw_conditions)
    elif raw_conditions is not None:
        n_conditions = 1
    else:
        n_conditions = None
    condition_mesh_branch = _condition_mesh_branch(record)
    raw_interventions = arms_block.get('interventions')
    n_interventions = None
    intervention_types = None
    if isinstance(raw_interventions, list):
        n_interventions = len(raw_interventions)
        type_values = []
        for item in raw_interventions:
            if isinstance(item, dict):
                label = _norm(item.get('type'))
            else:
                label = _norm(item)
            if label is not None:
                type_values.append(label.upper())
        if type_values:
            intervention_types = '|'.join(sorted(set(type_values)))
    elif raw_interventions is not None:
        n_interventions = 1
        if isinstance(raw_interventions, dict):
            label = _norm(raw_interventions.get('type'))
        else:
            label = _norm(raw_interventions)
        if label is not None:
            intervention_types = label.upper()
    raw_arms = arms_block.get('armGroups')
    if isinstance(raw_arms, list):
        n_arms = len(raw_arms)
    elif raw_arms is not None:
        n_arms = 1
    else:
        n_arms = None
    healthy_flag = _tri(eligibility_block.get('healthyVolunteers'))
    if healthy_flag is True:
        healthy_volunteers = 'YES'
    elif healthy_flag is False:
        healthy_volunteers = 'NO'
    else:
        healthy_volunteers = _norm(eligibility_block.get('healthyVolunteers'))
    sex = _norm(eligibility_block.get('sex'))
    minimum_age = _norm(eligibility_block.get('minimumAge'))
    maximum_age = _norm(eligibility_block.get('maximumAge'))
    if minimum_age is None and maximum_age is None:
        age_bounds = None
    else:
        min_years = _age_years(minimum_age)
        max_years = _age_years(maximum_age)
        if min_years is not None:
            pediatric = 'YES' if min_years < 18.0 else 'NO'
        elif max_years is not None:
            pediatric = 'YES' if max_years < 18.0 else 'NO'
        else:
            pediatric = 'UNKNOWN'
        age_bounds = 'min:' + (minimum_age if minimum_age is not None else 'UNKNOWN') + ';max:' + (maximum_age if maximum_age is not None else 'UNKNOWN') + ';pediatric:' + pediatric
    drug_flag = _tri(oversight_block.get('isFdaRegulatedDrug'))
    device_flag = _tri(oversight_block.get('isFdaRegulatedDevice'))
    if drug_flag is None and device_flag is None:
        is_fda_regulated = None
    else:
        is_fda_regulated = 'drug:' + _tri_label(drug_flag) + ';device:' + _tri_label(device_flag)
    start_raw = _deep(status_block, 'startDateStruct', 'date')
    if start_raw is None:
        start_raw = status_block.get('startDate')
    start_month = None
    start_ym = _parse_month(start_raw)
    if start_ym is not None:
        start_month = (first_post.year * 12 + first_post.month) - (start_ym[0] * 12 + start_ym[1])
    target_value = 1 if overall == 'TERMINATED' else 0
    return {
        ID_COL: nct_id,
        TIME_COL: first_post.isoformat(),
        'phase': phase,
        'allocation': allocation,
        'intervention_model': intervention_model,
        'masking': masking,
        'primary_purpose': primary_purpose,
        'lead_sponsor_class': lead_sponsor_class,
        'n_conditions': n_conditions,
        'condition_mesh_branch': condition_mesh_branch,
        'n_interventions': n_interventions,
        'intervention_types': intervention_types,
        'n_arms': n_arms,
        'healthy_volunteers': healthy_volunteers,
        'sex': sex,
        'age_bounds': age_bounds,
        'is_fda_regulated': is_fda_regulated,
        'start_month': start_month,
        TARGET: target_value,
    }


def build(output: Path, cache: Path):
    output = Path(output)
    cache = Path(cache)
    checks = []
    records = []
    totals = {}
    for status in ('COMPLETED', 'TERMINATED'):
        rows, total = _fetch_status(status, cache)
        totals[status] = total
        records.extend(rows)
        expected = EXPECTED_COUNTS[status]
        passed = total == expected and len(rows) == total
        checks.append({
            'check': 'publisher total count and fetched rows for ' + status,
            'observed': 'totalCount ' + str(total) + ' and fetched rows ' + str(len(rows)),
            'expected': 'supplied publisher snapshot count ' + str(expected) + ' with fetched rows equal to totalCount',
            'passed': passed,
        })
        if not passed:
            raise AssertionError(_bounded('Publisher count check failed for ' + status + '; observed_totalCount: ' + str(total) + '; fetched_rows: ' + str(len(rows)) + '; expected_totalCount: ' + str(expected) + '; selected_archive_member: N/A (JSON API).'))
    parsed = []
    for record in records:
        parsed.append(_parse_record(record))
    df = pd.DataFrame(parsed, columns=OUTPUT_COLUMNS)
    for column in ('n_conditions', 'n_interventions', 'n_arms', 'start_month'):
        df[column] = pd.to_numeric(df[column], errors='coerce').astype('Int64')
    df[TARGET] = df[TARGET].astype('int64')
    df = df.sort_values([TIME_COL, ID_COL], kind='mergesort').reset_index(drop=True)
    observed_headers = list(df.columns)
    missing = [name for name in OUTPUT_COLUMNS if name not in observed_headers]
    extra = [name for name in observed_headers if name not in OUTPUT_COLUMNS]
    header_ok = not missing and not extra
    checks.append({
        'check': 'output columns exactly match declared ID, time, features and target',
        'observed': repr(observed_headers),
        'expected': repr(OUTPUT_COLUMNS),
        'passed': header_ok,
    })
    if not header_ok:
        raise AssertionError(_field_failure('Output header check failed', observed_headers, missing, extra))
    unique_targets = sorted(int(item) for item in df[TARGET].dropna().unique().tolist())
    target_ok = df[TARGET].notna().all() and all(item in (0, 1) for item in unique_targets)
    checks.append({
        'check': 'target is binary with no missing labels',
        'observed': 'unique_target_values ' + repr(unique_targets) + ' and missing_count ' + str(int(df[TARGET].isna().sum())),
        'expected': 'values restricted to 0 and 1 with zero missing labels',
        'passed': target_ok,
    })
    if not target_ok:
        raise AssertionError(_field_failure('Target binary check failed', observed_headers, [TARGET]))
    duplicate_count = int(df[ID_COL].duplicated().sum())
    duplicate_ok = duplicate_count == 0
    checks.append({
        'check': 'NCT ID join key has no duplicates',
        'observed': 'duplicate_count ' + str(duplicate_count),
        'expected': 'zero duplicate NCT IDs because each study contributes one row',
        'passed': duplicate_ok,
    })
    if not duplicate_ok:
        sample_ids = df.loc[df[ID_COL].duplicated(keep=False), ID_COL].head(20).tolist()
        raise AssertionError(_field_failure('Duplicate NCT ID join-key check failed; duplicate_count: ' + str(duplicate_count) + '; sample_ids: ' + repr(sample_ids), observed_headers, [ID_COL]))
    coverage = {feature: int(df[feature].notna().sum()) for feature in FEATURES}
    empty_features = [feature for feature in FEATURES if coverage[feature] == 0]
    coverage_ok = not empty_features
    checks.append({
        'check': 'every declared feature has source-backed non-null coverage',
        'observed': repr(coverage),
        'expected': 'each declared feature has at least one non-null value; missing values remain empty and are not zero-filled',
        'passed': coverage_ok,
    })
    if not coverage_ok:
        raise AssertionError(_field_failure('Declared feature coverage check failed; observed_non_null_counts: ' + repr(coverage), observed_headers, empty_features))
    dates = pd.to_datetime(df[TIME_COL], errors='coerce')
    bad_date_count = int(dates.isna().sum())
    pop_start_ts = pd.Timestamp(POP_START)
    pop_end_ts = pd.Timestamp(POP_END)
    outside_count = int(((dates < pop_start_ts) | (dates >= pop_end_ts)).sum())
    time_ok = bad_date_count == 0 and outside_count == 0
    observed_min = dates.min().date().isoformat() if dates.notna().any() else 'none'
    observed_max = dates.max().date().isoformat() if dates.notna().any() else 'none'
    checks.append({
        'check': 'time join key and frozen population date range',
        'observed': 'bad_date_count ' + str(bad_date_count) + ', outside_count ' + str(outside_count) + ', minimum ' + observed_min + ', maximum ' + observed_max,
        'expected': 'valid ISO dates in the half-open window 2008-01-01 through 2017-01-01',
        'passed': time_ok,
    })
    if not time_ok:
        raise AssertionError(_field_failure('Time join-key and population date check failed; bad_date_count: ' + str(bad_date_count) + '; outside_count: ' + str(outside_count) + '; observed_minimum: ' + observed_min + '; observed_maximum: ' + observed_max, observed_headers, [TIME_COL]))
    start_values = df['start_month'].dropna()
    if len(start_values) == 0:
        start_min = 'none'
        start_max = 'none'
        non_integer_count = 0
    else:
        start_min = str(start_values.min())
        start_max = str(start_values.max())
        non_integer_count = int((start_values.astype('float64') % 1.0 != 0.0).sum())
    unit_ok = len(start_values) > 0 and non_integer_count == 0
    checks.append({
        'check': 'start_month has whole calendar-month units',
        'kind': 'unit',
        'observed': 'non_null ' + str(len(start_values)) + ', minimum ' + start_min + ', maximum ' + start_max + ', non_integer_count ' + str(non_integer_count),
        'expected': 'integer calendar-month differences; zero means the start month equals the first-post month; missing stays empty',
        'passed': unit_ok,
    })
    if not unit_ok:
        raise AssertionError(_bounded('Start-month unit check failed; observed_non_null: ' + str(len(start_values)) + '; observed_minimum: ' + start_min + '; observed_maximum: ' + start_max + '; non_integer_count: ' + str(non_integer_count) + '; selected_archive_member: N/A (JSON API).'))
    train_mask = (dates >= pd.Timestamp(TRAIN_START)) & (dates < pd.Timestamp(TRAIN_END))
    eval_mask = (dates >= pd.Timestamp(EVAL_START)) & (dates < pd.Timestamp(EVAL_END))
    holdout_mask = (dates >= pd.Timestamp(HOLDOUT_START)) & (dates < pd.Timestamp(HOLDOUT_END))
    assigned = train_mask | eval_mask | holdout_mask
    unassigned_count = int((~assigned).sum())
    split_counts = {'train': int(train_mask.sum()), 'eval': int(eval_mask.sum()), 'holdout': int(holdout_mask.sum())}
    split_ranges = {}
    for split_name, split_mask in (('train', train_mask), ('eval', eval_mask), ('holdout', holdout_mask)):
        part = dates[split_mask]
        if len(part) == 0:
            split_ranges[split_name] = 'empty'
        else:
            split_ranges[split_name] = part.min().date().isoformat() + '..' + part.max().date().isoformat()
    split_ok = unassigned_count == 0 and all(value > 0 for value in split_counts.values())
    checks.append({
        'check': 'fixed half-open chronological split windows cover every row',
        'observed': 'counts ' + repr(split_counts) + ', ranges ' + repr(split_ranges) + ', unassigned_count ' + str(unassigned_count),
        'expected': 'train 2008-01-01 through 2012-12-31, eval 2013-01-01 through 2014-12-31, holdout 2015-01-01 through 2016-12-31',
        'passed': split_ok,
    })
    if not split_ok:
        raise AssertionError(_bounded('Split window check failed; observed_counts: ' + repr(split_counts) + '; observed_ranges: ' + repr(split_ranges) + '; unassigned_count: ' + str(unassigned_count) + '; selected_archive_member: N/A (JSON API).'))
    sample_rows = df.loc[df[ID_COL] == 'NCT01533376']
    sample_present = len(sample_rows) == 1
    if sample_present:
        sample = sample_rows.iloc[0]
        sample_target = int(sample[TARGET])
        sample_phase = _norm(sample['phase'])
        sample_sponsor = _norm(sample['lead_sponsor_class'])
        sample_ok = sample_target == 1 and sample_phase == 'PHASE1' and sample_sponsor == 'OTHER'
        sample_observed = 'target ' + str(sample_target) + ', phase ' + repr(sample_phase) + ', lead_sponsor_class ' + repr(sample_sponsor)
    else:
        sample_ok = False
        sample_observed = 'row_count ' + str(len(sample_rows))
    checks.append({
        'check': 'concrete publisher example NCT01533376',
        'observed': sample_observed,
        'expected': 'target 1, phase PHASE1, lead_sponsor_class OTHER',
        'passed': sample_ok,
    })
    if not sample_ok:
        if not sample_present:
            raise AssertionError(_field_failure('Concrete source example row is missing', observed_headers, ['NCT01533376']))
        raise AssertionError(_bounded('Concrete source example check failed; observed_values: ' + sample_observed + '; expected: target 1, phase PHASE1, lead_sponsor_class OTHER; selected_archive_member: N/A (JSON API).'))
    train_df = df.loc[train_mask].copy()
    eval_df = df.loc[eval_mask].copy()
    holdout_df = df.loc[holdout_mask].copy()
    public_dir = output / 'public'
    private_dir = output / 'private'
    public_dir.mkdir(parents=True, exist_ok=True)
    private_dir.mkdir(parents=True, exist_ok=True)
    train_path = public_dir / 'train.csv'
    eval_path = public_dir / 'eval.csv'
    holdout_path = private_dir / 'holdout.csv'
    train_df.to_csv(train_path, index=False)
    eval_df.to_csv(eval_path, index=False)
    holdout_df.to_csv(holdout_path, index=False)
    written_headers = {}
    for path in (train_path, eval_path, holdout_path):
        frame = pd.read_csv(path, nrows=0)
        written_headers[str(path)] = list(frame.columns)
    headers_ok = all(header == OUTPUT_COLUMNS for header in written_headers.values())
    checks.append({
        'check': 'written CSV headers are identical and exact',
        'observed': repr(written_headers),
        'expected': repr(OUTPUT_COLUMNS),
        'passed': headers_ok,
    })
    if not headers_ok:
        observed = written_headers[str(train_path)]
        missing = [name for name in OUTPUT_COLUMNS if name not in observed]
        extra = [name for name in observed if name not in OUTPUT_COLUMNS]
        raise AssertionError(_field_failure('Written CSV header check failed', observed, missing, extra))
    return checks
